  "docs.audio.title": "Audio",
  "docs.audio.intro": "{name}'s audio APIs are aligned with the OpenAI <code>/v1/audio/*</code> protocol, providing both <strong>speech-to-text (ASR)</strong> and <strong>text-to-speech (TTS)</strong> capabilities. The backend connects to multiple upstreams including Tencent Cloud, OpenAI Whisper, MiniMax, Alibaba DashScope (CosyVoice TTS + Paraformer-v2 ASR), Volcengine Doubao, Deepgram, and ElevenLabs (since Phase 86, routing is automatic by <code>model→provider_type</code>).",
  "docs.audio.calloutRoutingTitle": "Routing & billing",
  "docs.audio.calloutRoutingBody": "Audio requests are routed to the matching channel by <code>model.provider_type</code> (e.g. <code>whisper-1</code>→openai, <code>speech-2.8-hd</code>→minimax, <code>dashscope-asr-paraformer-v2</code>→dashscope_speech, <code>asr-16k-zh</code>→asr_tencent). The optional <code>channel</code> field in the body or query can pin a specific channel under the same provider_type. Requests go through the <code>APIKeyAuth + RateLimit + QuotaCheck</code> trio, and each vendor is priced independently by its billing dimension. For unit prices, see the <code>audio</code>-type models in the model list.",
  "docs.audio.calloutIngestTitle": "Transparent ingest for URL-only upstreams (Phase 89e)",
  "docs.audio.calloutIngestBody": "Alibaba Paraformer-v2 (<code>dashscope_speech</code>) and the Volcengine Doubao ASR model (<code>volc_speech</code>) upstreams accept public URLs only, but the service layer transparently ingests the client's <code>audio_data</code> base64 / multipart <code>file</code> into the platform's <code>assets</code> table and forwards a signed reverse-proxy URL to the upstream, so <strong>all three input forms work from the client side</strong>. These two providers also have async-only pipelines, so the <strong>synchronous endpoint returns <code>synchronous ASR not supported</code> — use <code>/v1/audio/transcriptions/async</code> instead.</strong>",
  "docs.audio.calloutPollModelTitle": "Always include model when polling async",
  "docs.audio.calloutPollModelBody": "When polling <code>GET /v1/audio/transcriptions/{id}</code>, we <strong>strongly recommend including <code>?model=<the model used at submit></code></strong>. Before Phase 89d only Tencent had async Fetch, so falling back to the Tencent provider when model was missing was correct. After adding DashScope Paraformer, a UUID-shaped task_id passed to Tencent's ParseInt fails outright with <code>invalid upstream_id ... invalid syntax</code>. With <code>model</code> present, requests route to the correct provider by provider_type.",
  "docs.audio.asrHeading": "Speech-to-Text (ASR)",
  "docs.audio.asrIntro": "<code>POST {base}/audio/transcriptions</code> handles synchronous single-utterance recognition ≤ 60 seconds; <code>POST {base}/audio/transcriptions/async</code> plus polling <code>GET /:id</code> handles long recordings (up to several hours).",
  "docs.audio.syncRequestHeading": "Synchronous request",
  "docs.audio.asrSyncDesc": "Accepts both <strong>multipart/form-data</strong> (the OpenAI Whisper convention, 64MB max) and <strong>application/json</strong> (URL or inline base64, 20MB max).",
  "docs.audio.requestFieldsHeading": "Request fields",
  "docs.audio.colField": "Field",
  "docs.audio.colType": "Type",
  "docs.audio.colDesc": "Description",
  "docs.audio.required": "Required",
  "docs.audio.requiredMultipart": "Required for multipart",
  "docs.audio.asrFieldModelDesc": "ASR model ID. For sync: <code>asr-16k-zh</code> / <code>asr-16k-zh-en</code> / <code>asr-16k-en</code> / <code>asr-16k-ja</code> / <code>asr-16k-ko</code> / <code>asr-8k-zh</code> (telephony); for async recordings use the <code>asr-recfile-*</code> series.",
  "docs.audio.asrFieldFileDesc": "Attach the file directly when uploading via multipart; <code>format</code> can be inferred from the filename extension as a fallback.",
  "docs.audio.asrFieldUrlDesc": "In JSON mode, a publicly reachable audio file URL. Use either this or <code>audio_data</code>.",
  "docs.audio.asrFieldAudioDataDesc": "In JSON mode, base64-encoded audio content; a <code>data:audio/wav;base64,...</code> prefix is tolerated. Up to 20MB (after base64). Use either this or <code>url</code>.",
  "docs.audio.asrFieldFormatDesc": "Audio container format: <code>wav</code> / <code>mp3</code> / <code>m4a</code> / <code>flac</code> / <code>pcm</code>.",
